        assert.notOk(res.active);
    });

    test('fresh latch is active — the armer must log and dispatch nothing (AC1)', function () {
        var map = latch.arm({}, 1428, HEAD, T0);
        var res = latch.isActive(map, 1428, HEAD, { now: T0_MS + TEN_MIN });
