        assert.ok(res.active);
        assert.equal(res.cause, 'in-flight');
    });
});

// ── stale self-heal (AC3) ────────────────────────────────────────────────────

suite('reworkLatch — stale timeout (AC3: 45 min, no matching active run)', function () {
